1: <template>
2:   <div class="appendix-package-section entrust-sale-add-appendix" data-testid="entrust-sale-appendix">
3:     <AppendixRequirementGrid
4:       v-if="displayFileList.length"
5:       :file-list="displayFileList"
6:       :operable="true"
7:       :types="fileTypeOptions"
8:       :upload-file-url="uploadFileUrl"
9:       :headers="headers"
10:       :upload-data="uploadData"
11:       :on-before-upload="handleBeforeUpload"
12:       :on-upload-error="handleUploadError"
13:       :on-exceed="handleExceed"
14:       :on-upload-success="handleUploadSuccess"
15:       :on-remove-file="removeAppendixFile"
16:       @onRemove="handleDelete"
17:       @onDownload="handleDownload" />
