22: <script>
23: import AppendixRequirementGrid from '@/components/AnnexUpload/components/AppendixRequirementGrid.vue'
24: import { getToken } from '@/utils/auth.js'
25: import { resolveServerAssetUrl } from '@/utils/resolveServerAssetUrl.js'
26: 
27: export default {
28:   name: 'EntrustSaleAddAppendix',
29:   components: { AppendixRequirementGrid },
30:   props: {
31:     value: {
32:       type: Array,
33:       default: () => []
34:     }
35:   },
36:   data() {
37:     return {
38:       fileList: [],
39:       uploadedFiles: [],
40:       fileTypeOptions: [],
41:       checkInfo: null,
42:       uploadFileUrl: import.meta.env.VITE_APP_BASE_API + '/file/appendix/upload'
43:     }
44:   },
45:   computed: {
46:     headers() {
47:       return {
48:         Authorization: 'Bearer ' + getToken()
49:       }
50:     },
51:     appendixIds() {
52:       return this.uploadedFiles.map((item) => item.appendixId)
53:     },
54:     displayFileList() {
55:       return this.fileList.map((item) => ({
56:         ...item,
57:         appendices: this.getAppendicesForConfig(item.appendixConfigId)
58:       }))
59:     }
60:   },
61:   watch: {
62:     appendixIds: {
63:       handler(val) {
64:         this.$emit('input', val)
65:         this.$emit('change', val)
66:       },
67:       deep: true
68:     }
69:   },
70:   created() {
71:     this.loadConfig()
72:     this.initDict()
73:   },
74:   methods: {
75:     loadConfig() {
76:       this.$post('/file/appendix/listAppendixPackage', {
77:         busCode: 'wtds'
78:       }).then((res) => {
79:         let tmp = undefined
80:         this.fileList = (res.data || []).map((item) => {
81:           let isMenu = false
82:           if (tmp != item.menuName) {
83:             tmp = item.menuName
84:             isMenu = true
85:           }
86:           return {
87:             ...item.appendixConfig,
88:             menuName: item.menuName,
89:             isMenu,
90:             fileDirVersionId: item.fileDirVersionId,
91:             versionNo: item.versionNo,
92:             busCode: 'wtds'
93:           }
94:         })
95:       })
96:     },
97:     initDict() {
98:       this.getDicts('file_type').then((response) => {
99:         this.fileTypeOptions = response.data || []
100:       })
101:     },
102:     uploadData(item) {
103:       return {
104:         busCode: 'wtds',
105:         appendixConfigId: item.appendixConfigId,
106:         fileDirVersionId: item.fileDirVersionId || ''
107:       }
108:     },
109:     getAcceptFileType(type) {
110:       if (!type) return ''
111:       return this.fileTypeOptions
112:         .filter((item) => type.includes(item.dictValue))
113:         .map((item) => item.remark)
114:         .join(',')
115:     },
116:     getAppendicesForConfig(configId) {
117:       return this.uploadedFiles
118:         .filter((item) => item.appendixConfigId === configId)
119:         .map((item) => ({
120:           appendixId: item.appendixId,
121:           appendixConfigId: item.appendixConfigId,
122:           fileName: item.fileName || item.appendixName || item.name,
123:           fileSite: item.fileSite,
124:           fileThumbnailSite: item.fileThumbnailSite,
125:           fileType: item.fileType,
126:           remark: item.remark
127:         }))
128:     },
129:     handleBeforeUpload(file, item) {
130:       this.checkInfo = item
131:       const type = item.fileType
132:       const acceptTypes = this.getAcceptFileType(type)
133:       if (acceptTypes) {
134:         const currentType = file.name.slice(file.name.lastIndexOf('.') + 1)
135:         if (!acceptTypes.includes(currentType)) {
136:           this.$message.error('请上传正确的文件类型')
137:           return false
138:         }
139:       }
140:       const maxSize = Number(item.fileMaxSize || 5 * 1024 * 1024)
141:       const minSize = Number(item.fileMinSize || 0)
142:       if (file.size === 0) {
143:         this.$message.error('该文件内容为空!')
144:         return false
145:       }
146:       if (file.size > maxSize) {
147:         this.$message.error(`上传文件大小不能超过 ${this.getFileSizeUnit(maxSize)}!`)
148:         return false
149:       }
150:       if (minSize && file.size < minSize) {
151:         this.$message.error(`上传文件大小不能低于 ${this.getFileSizeUnit(minSize)}!`)
152:         return false
153:       }
154:       return true
155:     },
156:     getFileSizeUnit(size) {
157:       let data = size
158:       if (size < 0.1 * 1024) {
159:         data = size.toFixed(2) + 'B'
160:       } else if (size < 0.1 * 1024 * 1024) {
161:         data = (size / 1024).toFixed(2) + 'KB'
162:       } else if (size < 0.1 * 1024 * 1024 * 1024) {
163:         data = (size / (1024 * 1024)).toFixed(2) + 'MB'
164:       } else {
165:         data = (size / (1024 * 1024 * 1024)).toFixed(2) + 'GB'
166:       }
167:       return data
168:     },
169:     handleExceed(files, fileList) {
170:       this.$message.error(`上传文件数量不能超过 ${fileList.length} 个!`)
171:     },
172:     handleUploadSuccess(res, file) {
173:       if (res.code !== 200) {
174:         this.$message.error(res.msg || '上传失败')
175:         return
176:       }
177:       const appendixId = res.data?.appendixId || res.data
178:       const data = res.data && typeof res.data === 'object' ? res.data : {}
179:       this.uploadedFiles.push({
180:         appendixId,
181:         appendixConfigId: this.checkInfo.appendixConfigId,
182:         appendixName: file.name,
183:         fileName: data.fileName || file.name,
184:         name: file.name,
185:         fileSite: data.fileSite,
186:         fileThumbnailSite: data.fileThumbnailSite,
187:         fileType: data.fileType || file.name.slice(file.name.lastIndexOf('.') + 1),
188:         remark: data.remark
189:       })
190:       this.$message.success('上传成功')
191:     },
192:     handleUploadError(err) {
193:       try {
194:         const errorData = JSON.parse(err.message)
195:         this.$message.error(errorData.msg || '上传失败')
196:       } catch (e) {
197:         this.$message.error('上传失败')
198:       }
199:     },
200:     handleDelete(id) {
201:       if (!id) {
202:         return
203:       }
204:       const ids = Array.isArray(id) ? id : [id]
205:       this.$post('/file/appendix/delete', ids).then((res) => {
206:         if (res.code === 200) {
207:           this.uploadedFiles = this.uploadedFiles.filter(
208:             (item) => !ids.includes(item.appendixId)
209:           )
210:           this.$message.success('删除成功')
211:         }
212:       })
213:     },
214:     removeAppendixFile(id) {
215:       if (!id) {
216:         return Promise.reject(new Error('missing appendix id'))
217:       }
218:       return this.$post('/file/appendix/delete', [id]).then((res) => {
219:         if (res.code === 200) {
220:           this.uploadedFiles = this.uploadedFiles.filter((item) => item.appendixId !== id)
221:           this.$message.success('删除成功')
222:           return true
223:         }
224:         this.$message.error(res.msg || '删除失败')
225:         return Promise.reject(new Error('delete failed'))
226:       })
227:     },
228:     handleDownload(item) {
229:       if (!item.fileSite) {
230:         this.$message.warning('暂无可下载的文件')
231:         return
232:       }
233:       fetch(resolveServerAssetUrl(item.fileSite))
234:         .then((res) => res.blob())
235:         .then((res) => {
236:           const elink = document.createElement('a')
237:           elink.download = item.fileName
238:           elink.href = URL.createObjectURL(res)
239:           elink.click()
240:           URL.revokeObjectURL(elink.href)
241:         })
242:     },
243:     getUploadedCount(configId) {
244:       return this.uploadedFiles.filter((item) => item.appendixConfigId === configId).length
245:     },
246:     validateRequired() {
247:       const requiredConfigs = this.fileList.filter((item) => item.isRequired === '1')
248:       const missing = requiredConfigs.filter((item) => !this.getUploadedCount(item.appendixConfigId))
249:       if (missing.length) {
250:         this.$message.warning(`请上传必填要件：${missing.map((item) => item.appendixConfigName).join('、')}`)
251:         return false
252:       }
253:       return true
254:     }
255:   }
256: }
257: </script>

