1: /** 去掉误拼在 API 前缀下的静态资源路径，如 /v3.0/zhi2-dev/... → /zhi2-dev/... */
2: function normalizeServerAssetPath(path) {
3:   return path.replace(/^\/(?:api\/)?v3\.0\/(zhi2(?:-dev|-test)?\/)/i, '/$1')
4: }
5: 
6: /**
7:  * 将后端返回的站内绝对路径（如 /zhi2/xxx、/uploads/xxx）转为浏览器可请求的完整 URL。
8:  * 去掉首部的 / 后，按「相对当前页面地址」解析（与 import 的相对路径规则一致），部署在 /sz 等子路径下会自动落在正确前缀下，无需 VITE_APP_PUBLIC_PATH。
9:  * 已是 http(s)://、//、data:、blob: 的路径，以及不以 / 开头的地址（含 import 静态资源）均原样返回。
10:  * 站点入口建议配置为带尾斜杠的地址（如 …/sz/），避免出现 …/sz 无斜杠时浏览器把最后一段当「文件名」导致相对路径拼错。
11:  */
12: export function resolveServerAssetUrl(input) {
13:   if (input == null || input === '') return ''
14:   let path = String(input).trim()
15:   if (!path) return ''
16: 
17:   if (/^(https?:\/\/|\/\/|data:|blob:)/i.test(path)) {
18:     return path
19:   }
20: 
21:   if (!path.startsWith('/')) {
22:     return path
23:   }
24: 
25:   path = normalizeServerAssetPath(path)
26: 
27:   if (path.startsWith('/@') || path.startsWith('/src/')) {
28:     return path
29:   }
30: 
